                    style={{
                      position: 'relative',
                      zIndex: 1,
                      fontSize: 11,
                      padding: ws === 'text' ? '2px 6px' : '3px 10px',
                      borderRadius: ws === 'rounded' ? 999 : 4,
                      border: 'none',
                      cursor: 'pointer',
                      fontFamily: 'system-ui, -apple-system, sans-serif',
                      fontWeight: isActive ? 600 : 400,
                      background: 'transparent',
