                aria-label="Candlestick"
                aria-pressed={activeMode === 'candle'}
                className={focusRing}
                onClick={() => onModeChange('candle')}
                style={{
                  position: 'relative',
                  zIndex: 1,
                  padding: '5px 7px',
                  borderRadius: ws === 'rounded' ? 999 : 4,
                  border: 'none',
                  cursor: 'pointer',
                  background: 'transparent',
                  display: 'flex',
                  alignItems: 'center',
                }}
              >
                <svg width="12" height="12" viewBox="0 0 12 12" fill="none" aria-hidden="true">
